const D = { energy:.6, scale:1, density:.4, speed:1, circuits:.12, hue:38, x:.5, y:.5, style:'stone', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// RESCUE NOTE: v1 drew the path as a hairline (pw ~.02u) in light stroke on a
// near-black ground (b=10..20), with the disc at .44u so half the frame was
// dead. It read as flat clipart at lum .227. Now: the MATERIAL fills the whole
// frame (a worn pavement, textured, precessing with the labyrinth because the
// path is cut INTO it), the disc is .82u so the figure covers ~85% of frame,
// the path is an incised channel with a lit lip and a shadowed lip that swap
// sides as the lamp rakes, and a lamp pool sweeps the floor for a real motion
// floor at incommensurate K.t rates.

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const TAU = Math.PI*2;
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };

const sty = P.style;
const bp = (sty==='blueprint'), paper = (sty==='engraving'), thread = (sty==='thread'), turf = (sty==='turf');
const H = ((P.hue%360)+360)%360;
const NC = [7,11,15,19][cl(Math.floor(cl(P.circuits,0,1)*3.999), 0, 3)];   // classical circuit counts
const RAD = u*.82*cl(P.scale,.35,2.0);
const cx = cl(P.x,.1,.9)*width, cy = cl(P.y,.1,.9)*height;
const RIN = .12;                                    // goal radius, normalised
const drn = (1-RIN)/(NC+1);                         // circuit spacing, normalised
const pw = Math.max(3, RAD*drn*.62);                // the incised channel width

// ---- the classical (Cretan / Chartres) level sequence -----------------------
function levelSeq(N){
  const q = [];
  for (let k=(N-1)/2; k>=1; k--) q.push(k);
  q.push((N+1)/2);
  for (let k=N; k>=(N+3)/2; k--) q.push(k);
  q.push(N+1);
  return q;
}
// ---- build the ONE unicursal path (normalised radius, angle) ---------------
if (S.ncU !== NC){
  S.ncU = NC;
  const seq = levelSeq(NC), eps = .105, th0 = Math.PI/2;
  const nrOf = lv => 1 - lv*drn;
  let cth = th0 + eps;
  const pts = [[nrOf(0)*1.14, cth]];
  for (let i=0;i<seq.length;i++){
    const dir = (i%2===0) ? 1 : -1;
    const nr = nrOf(seq[i]);
    pts.push([nr, cth]);
    if (i === seq.length-1) break;
    const sw = TAU - 2*eps, ST = 56;
    for (let j=1;j<=ST;j++) pts.push([nr, cth + dir*sw*j/ST]);
    cth += dir*sw;
  }
  let tot = 0; const cum = [0];
  for (let i=1;i<pts.length;i++){
    const a = pts[i-1], b = pts[i];
    const ax = a[0]*Math.cos(a[1]), ay = a[0]*Math.sin(a[1]);
    const bx = b[0]*Math.cos(b[1]), by = b[0]*Math.sin(b[1]);
    tot += Math.hypot(bx-ax, by-ay); cum.push(tot);
  }
  const M = 780, rs = [];
  let idx = 1;
  for (let m=0;m<=M;m++){
    const d = tot*m/M;
    while (idx < cum.length-1 && cum[idx] < d) idx++;
    const c0 = cum[idx-1], c1 = cum[idx], s = (c1>c0) ? (d-c0)/(c1-c0) : 0;
    const a = pts[idx-1], b = pts[idx];
    rs.push([a[0] + (b[0]-a[0])*s, a[1] + (b[1]-a[1])*s]);
  }
  S.pts = pts; S.rs = rs;
}
const pts = S.pts, rs = S.rs;

// ---- motion ----------------------------------------------------------------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.w = (S.w||0) + dt * P.speed * .0125 * (.5 + .8*K.intensity) * (.5 + .8*P.energy);
const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
const glow = (.40 + .60*P.energy)*(.55 + .5*K.intensity) + bass*.35;
const rot = K.t*.021 + .13*Math.sin(K.t*.077) + .06*Math.sin(K.t*.191+1.2);
const NW = Math.max(1, 1 + Math.round(cl(P.density,0,1)*3));
// the lamp: rakes across the floor on two incommensurate rates, so the incised
// lips swap sides and the pool crawls — the piece is never the same 8s later
const laz = K.t*.037 + .70*Math.sin(K.t*.019+.4) + .28*Math.sin(K.t*.0083);
const lpx = cx + Math.cos(laz*.63 + .8)*width*.30 + Math.sin(K.t*.011)*width*.08;
const lpy = cy + Math.sin(laz*.51)*height*.30 + Math.cos(K.t*.0157)*height*.07;

// ---- palette ---------------------------------------------------------------
// MATERIAL is the base colour of the floor itself; TROUGH is the recessed
// channel floor; LIP is stone catching the lamp; SHAD is the shadowed lip.
let MAT, JOINT, TROUGH, LIP, SHAD, LITE;
if (bp)         { MAT=[212,55,30]; JOINT=[200,30,74]; TROUGH=[214,62,18]; LIP=[196,20,96]; SHAD=[216,66,12]; LITE=[186,26,100]; }
else if (paper) { MAT=[40,12,68];  JOINT=[32,26,34];  TROUGH=[34,22,40];  LIP=[42,6,92];   SHAD=[30,30,24];  LITE=[34,44,74]; }
else if (thread){ MAT=[230,44,9];  JOINT=[230,30,16]; TROUGH=[230,44,7];  LIP=[H,26,100];  SHAD=[230,50,4];  LITE=[H,26,100]; }
else if (turf)  { MAT=[96,42,44];  JOINT=[92,46,30];  TROUGH=[30,38,30];  LIP=[74,34,70];  SHAD=[96,50,16];  LITE=[52,50,96]; }
else            { MAT=[H-8,10,48]; JOINT=[H-10,18,24]; TROUGH=[H-6,14,30]; LIP=[H+2,7,82]; SHAD=[H-12,20,15]; LITE=[H+8,40,100]; }

// ---- the material: a full-frame worn floor, blitted rotated -----------------
// Sized to the frame DIAGONAL so the precessing floor always covers the canvas.
// This is the fix for "enormous dead space": there is no ground left unmade.
const BS = Math.ceil(Math.hypot(width, height)) + 2;
const ck = [BS, sty, Math.round(H), sd].join('|');
if (!S.mat || S.ck !== ck){
  if (S.mat) { try { S.mat.remove(); } catch(e){} }
  const g = createGraphics(BS, BS); g.pixelDensity(1); g.colorMode(HSB,360,100,100,100);
  g.noStroke(); g.background(MAT[0], MAT[1], MAT[2]);
  const U = BS/1400;
  if (turf){
    for (let i=0;i<26000;i++){                                  // sward
      const x=fr(i*1.7)*BS, y=fr(i*2.3)*BS, l2=(2+fr(i*3.1)*5)*U;
      g.stroke(MAT[0]+(fr(i*4.3)-.5)*26, MAT[1]+fr(i*5.1)*18, MAT[2]*(.5+fr(i*6.1)*1.1), 46);
      g.strokeWeight(U); g.line(x, y, x+(fr(i*5.7)-.5)*3*U, y-l2);
    }
    g.noStroke();
  } else if (bp){
    g.stroke(JOINT[0], JOINT[1], JOINT[2], 12); g.strokeWeight(Math.max(1,U));
    for (let i=0;i*34*U<BS;i++){ g.line(i*34*U,0,i*34*U,BS); g.line(0,i*34*U,BS,i*34*U); }
    g.noStroke();
    for (let i=0;i<5000;i++) { g.fill(MAT[0], MAT[1]*.8, MAT[2]*1.5, 6); g.circle(fr(i*11)*BS, fr(i*13)*BS, U*1.6); }
  } else if (paper){
    g.strokeWeight(Math.max(1,U));
    for (let i=0;i*26*U<BS;i++){ g.stroke(MAT[0], MAT[1]+6, MAT[2]-9, 12); g.line(i*26*U,0,i*26*U,BS); }
    for (let i=0;i<9000;i++){ const x=fr(i*19)*BS, y=fr(i*19+1)*BS, a=fr(i*19+2)*TAU, L=(2+fr(i*19+3)*11)*U;
      g.stroke(MAT[0], MAT[1]+9, MAT[2]+13, 7+fr(i*19+4)*12); g.line(x,y,x+Math.cos(a)*L,y+Math.sin(a)*L); }
    g.noStroke();
  } else if (thread){
    for (let i=0;i<7000;i++){ g.fill(MAT[0]+(fr(i*7)-.5)*30, MAT[1], MAT[2]*(1+fr(i*9)*3), 10);
      g.circle(fr(i*11)*BS, fr(i*13)*BS, (1+fr(i*17)*3)*U); }
  } else {
    // worn limestone flags: slab joints, aggregate, scratches, damp blooms
    const fl = Math.max(40, RAD*.34);
    g.strokeWeight(Math.max(1.5, U*2.2)); g.stroke(JOINT[0], JOINT[1], JOINT[2], 66);
    for (let i=0;i*fl<BS;i++){
      const jx = i*fl + (fr(i*3.3)-.5)*fl*.14;
      g.line(jx, 0, jx + (fr(i*4.1)-.5)*fl*.1, BS);
      const jy = i*fl + (fr(i*5.3)-.5)*fl*.14;
      g.line(0, jy, BS, jy + (fr(i*6.1)-.5)*fl*.1);
    }
    g.noStroke();
    for (let i=0;i<9000;i++){                                    // aggregate
      const x=fr(i*1.9)*BS, y=fr(i*2.7)*BS;
      g.fill(MAT[0]+(fr(i*3.1)-.5)*20, MAT[1]*(.4+fr(i*4.7)), MAT[2]*(.55+fr(i*5.9)*1.05), 30);
      g.circle(x, y, (.9+fr(i*6.7)*2.6)*U);
    }
    g.strokeWeight(Math.max(1,U));
    for (let i=0;i<2200;i++){                                    // scuff scratches
      const x=fr(i*7.1)*BS, y=fr(i*8.3)*BS, a=fr(i*9.1)*TAU, L=(4+fr(i*10.3)*22)*U;
      g.stroke(MAT[0], MAT[1]+6, MAT[2]*(fr(i*11.7)>.5?1.35:.6), 16);
      g.line(x,y,x+Math.cos(a)*L,y+Math.sin(a)*L);
    }
    g.noStroke();
    for (let i=0;i<160;i++){                                     // damp / wear blooms
      g.fill(MAT[0]+(fr(i*13)-.5)*16, MAT[1]+fr(i*17)*14, MAT[2]*(.7+fr(i*19)*.5), 12);
      g.ellipse(fr(i*23)*BS, fr(i*29)*BS, (40+fr(i*31)*230)*U, (40+fr(i*37)*230)*U);
    }
  }
  S.mat = g; S.ck = ck;
}

// The floor is the WORLD, so it is centred on the frame and sized to the frame
// diagonal — that way it covers the canvas at any rotation. The labyrinth is
// anchored at P.x/P.y separately; both share `rot`, so the path stays cut into
// the stone. (Centring the material on the anchor would uncover a corner as
// soon as P.x/P.y left the middle.)
push(); translate(width/2, height/2); rotate(rot);
image(S.mat, -BS/2, -BS/2);
pop();

push(); translate(cx, cy); rotate(rot);

// ---- the path, INCISED into the floor --------------------------------------
const PXY = p => [p[0]*RAD*Math.cos(p[1]), p[0]*RAD*Math.sin(p[1])];
const stroke_path = (src, ox, oy, w, c, a) => {
  stroke(c[0], c[1], c[2], a); strokeWeight(w);
  beginShape();
  for (let i=0;i<src.length;i++){ const q=PXY(src[i]); vertex(q[0]+ox, q[1]+oy); }
  endShape();
};
strokeCap(ROUND); strokeJoin(ROUND); noFill();
const ll = laz - rot;                       // lamp direction inside the turning floor
const off = pw*.17*(.5 + .8*P.energy);
const ox = Math.cos(ll)*off, oy = Math.sin(ll)*off;
if (!thread){
  stroke_path(pts,  ox,  oy, pw*1.30, LIP,  86);   // the lip catching the lamp
  stroke_path(pts, -ox, -oy, pw*1.30, SHAD, 90);   // the lip in its own shadow
  stroke_path(pts,   0,   0, pw,      TROUGH, 100);// the worn channel floor
  // grit in the channel
  stroke(LIP[0], LIP[1], LIP[2], 20); strokeWeight(Math.max(1, pw*.10));
  for (let i=0;i<rs.length;i+=7){
    const q=PXY(rs[i]), j=fr(i*1.3);
    line(q[0]+(j-.5)*pw*.5, q[1]+(fr(i*2.1)-.5)*pw*.5, q[0]+(fr(i*3.7)-.5)*pw*.5, q[1]+(fr(i*4.3)-.5)*pw*.5);
  }
} else {
  stroke_path(pts, 0, 0, pw*1.5, [LITE[0], cl(LITE[1]*.9,0,100), 56], 55);
  stroke_path(pts, 0, 0, Math.max(1.2, pw*.34), [LITE[0], LITE[1], 100], 92);
}

// ---- walkers: a lit head with a decaying trail, threading the one path -----
const M = rs.length - 1, TL = Math.round(M*.13);
push(); blendMode(ADD); noFill();
for (let w=0; w<NW; w++){
  const prog = ((S.w + w/NW) % 1 + 1) % 1;
  const hi = Math.floor(prog*M);
  const hw = (H + w*47) % 360;
  for (let b2=0;b2<6;b2++){
    const q0 = b2/6, q1 = (b2+1)/6;
    const i0 = Math.max(0, hi - Math.round(TL*(1-q0))), i1 = Math.max(0, hi - Math.round(TL*(1-q1)));
    if (i1 <= i0) continue;
    stroke(thread?hw:LITE[0], cl((thread?40:LITE[1])*(1-q1*.4),0,100), 100, cl((1.6 + 9*glow)*(q0*q0*1.2+.10), 0, 30));
    strokeWeight(pw*(.42 + .55*q1));
    beginShape(); for (let i=i0;i<=i1;i++){ const q=PXY(rs[i]); vertex(q[0],q[1]); } endShape();
  }
  const hd = PXY(rs[hi]);
  noStroke();
  for (let i=4;i>=1;i--){ fill(thread?hw:LITE[0], cl(LITE[1]*.8,0,100), 100, cl(3 + 9*glow, 0, 20));
    ellipse(hd[0], hd[1], pw*(.7+.85*i), pw*(.7+.85*i)); }
  noFill();
}
pop(); blendMode(BLEND);

// ---- the goal rosette at the centre ---------------------------------------
const pet = 6, rr = RAD*RIN*.92, rz = rot*.5 + K.t*.031;
noFill(); stroke(thread?LITE[0]:SHAD[0], thread?LITE[1]:SHAD[1], thread?100:SHAD[2], thread?70:92);
strokeWeight(Math.max(1.4, pw*.34));
for (let i=0;i<pet;i++){ const a=rz + i*TAU/pet;
  beginShape();
  for (let j=0;j<=14;j++){ const s=j/14, ang=a - .52 + 1.04*s;
    const q = rr*(.30 + .70*Math.sin(s*Math.PI));
    vertex(Math.cos(ang)*q*1.6, Math.sin(ang)*q*1.6); }
  endShape();
}
if (!thread){ noStroke(); fill(TROUGH[0], TROUGH[1], TROUGH[2], 100); ellipse(0,0, rr*.62, rr*.62); }
push(); blendMode(ADD); noStroke();
for (let i=3;i>=1;i--){ fill(LITE[0], cl(LITE[1]*.7,0,100), 100, 1.6 + 3.6*glow*(.5+.5*K.swell));
  ellipse(0, 0, rr*(1.1+.9*i), rr*(1.1+.9*i)); }
pop(); blendMode(BLEND);
pop();

// ---- the lamp pool: raking light crawling the floor in WORLD space ----------
// The floor turns under it; the lamp stays in the room. This sweeps a broad
// luminance gradient across the frame and is the primary motion floor.
{
  const dc = drawingContext, R2 = u*(.72 + .16*Math.sin(K.t*.027));
  const c = color(LITE[0], cl(LITE[1]*.45,0,100), 100);
  const cs = Math.round(red(c))+','+Math.round(green(c))+','+Math.round(blue(c));
  const g2 = dc.createRadialGradient(lpx, lpy, 0, lpx, lpy, R2);
  const pk = cl((.055 + .10*P.energy)*(.6 + .6*K.intensity), 0, .20);
  g2.addColorStop(0, 'rgba('+cs+','+pk.toFixed(4)+')');
  g2.addColorStop(.5, 'rgba('+cs+','+(pk*.42).toFixed(4)+')');
  g2.addColorStop(1, 'rgba('+cs+',0)');
  const oldOp = dc.globalCompositeOperation;
  dc.globalCompositeOperation = 'lighter';
  dc.fillStyle = g2; dc.fillRect(0,0,width,height);
  dc.globalCompositeOperation = oldOp;
}

if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1); strokeCap(ROUND);
